/**
 * What SPEC.md calls a number: no leading `+`, no leading zero, no bare `.5`,
 * and neither `NaN` nor `Infinity`.
 */
const NUMBER = /^-?(0|[1-9][0-9]*)(\.[0-9]+)?([eE][+-]?[0-9]+)?$/;

/**
 * @param {string} value a cell
 * @returns {boolean} whether it is a number
 */
function isNumber(value) {
  return NUMBER.test(value);
}

/**
 * @param {number} value a count or a result
 * @returns {string} it rounded to six decimal places, an integer kept plain
 */
function printNumber(value) {
  return String(Math.round(value * 1e6) / 1e6);
}

/**
 * Summarise the numeric columns of a table.
 *
 * A column is numeric when it has at least one non-empty value and every
 * non-empty value in it is a number; empty values are skipped rather than
 * counted.
 *
 * @param {Table} table the input table
 * @returns {Table} the header `column,count,min,max,mean` and one row per numeric column
 */
export function stats(table) {
  /** @type {string[][]} */
  const rows = [];

  table.header.forEach((name, column) => {
    /** @type {number[]} */
    const values = [];
    for (const row of table.rows) {
      const cell = row[column];
      if (cell === '') {
        continue;
      }
      if (!isNumber(cell)) {
