        return;
      }
      values.push(Number(cell));
    }
    if (values.length === 0) {
      // A column of only empty values, or of no values at all, is not numeric.
      return;
    }

    let min = values[0];
    let max = values[0];
    let total = 0;
    for (const value of values) {
      if (value < min) {
        min = value;
      }
      if (value > max) {
        max = value;
      }
      total += value;
    }

    rows.push([
      name,
      printNumber(values.length),
      printNumber(min),
      printNumber(max),
      printNumber(total / values.length),
    ]);
